 p=Path(row['path']);assert sha(p)==row['sha256'];e=json.loads(p.read_text());items.append({'ordinal':ordinal,'id':row['id'],'term':row['term'],'path':str(p.relative_to(ROOT)),'sha256':row['sha256'],'preferredTargets':[s['PreferredTarget'] for s in e['Senses']],'senseCount':len(e['Senses']),'occurrenceCount':sum(len(s.get('Occurrences',[])) for s in e['Senses']),'claimAnchorCount':sum(len(s.get('ClaimAnchors',[])) for s in e['Senses']),'reviewQuestions':['Does each opening state a term-specific corpus fact rather than annotation process?','Does each sense represent a different thing rather than a different reading or grammatical role?','Does the English stay within the exact full cases and avoid imported Buddhist, meditation, Japanese, or symbolic framing?','Are exact actors, narrated actions, impersonal headings, questioners, respondents, and contextual masters separated correctly?','Are high-frequency deployments broad enough without padding duplicates, and are all work-spread claims based on work_id?','Did corpus expansion expose a counterexample, new referent, or missing definition that changes the inherited article?'],'independentVerdict':None,'independentReviewer':None,'reviewNotes':None})
